const trials = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/study/NCT"]'));
  const map = new Map();
  for (const a of links) {
    const match = a.href.match(/(https:\/\/clinicaltrials\.gov\/study\/NCT\d+)/);
    if (match) {
      const cleanUrl = match[1];
      const text = a.textContent.trim();
      if (!map.has(cleanUrl) || (map.get(cleanUrl).text.length < text.length && !text.includes('Show all') && !text.includes('Find contact') && !text.includes('Check who'))) {
        map.set(cleanUrl, { url: cleanUrl, text });
      }
    }
  }
  return Array.from(map.values());
});
