const trialsToOpen = [
  "NCT07286149",
  "NCT06788912",
  "NCT06780098",
  "NCT06764771",
  "NCT07099898"
];

// Read existing trials data or initialize
let allTrials = [];
try {
  const existing = await read("tmp://trials_data.json");
  if (existing && existing.text) {
    allTrials = JSON.parse(existing.text);
  }
} catch (e) {
  allTrials = [];
}

// Add NCT05918783 if not already in allTrials
if (!allTrials.some(t => t.nct === "NCT05918783")) {
  allTrials.push({
    tabId: 787784140,
    nct: "NCT05918783",
    title: "Padeliporfin VTP Using Robotic Assisted Bronchoscopy in Peripheral Lung Cancer",
    intervention: "Combination Product: Padeliporfin Vascular Targeted Photodynamic (VTP) therapy",
    phase: "Phase 1",
    status: "Recruiting",
    locations: "Baltimore, Maryland (Johns Hopkins University School of Medicine)",
    url: "https://clinicaltrials.gov/study/NCT05918783"
  });
}

for (const nct of trialsToOpen) {
  const url = `https://clinicaltrials.gov/study/${nct}`;
  const tabRes = await tool.tabs_create({ url });
  const tabId = tabRes.details.tabId;
  console.log(`Created tab ${tabId} for ${nct}`);

  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "#study-overview", timeout_ms: 10000 });

  const extracted = await browserjs(tabId, () => {
    let title = '';
    const titleParts = document.title.split('|');
    if (titleParts.length >= 3) {
      title = titleParts[2].trim();
    } else {
      title = document.querySelector('h1')?.innerText?.trim() || document.title;
    }

    const fullText = document.body.innerText;

    // Status
    let status = 'Unknown';
    if (fullText.includes('Recruiting') && !fullText.includes('Not yet recruiting')) {
      status = 'Recruiting';
    } else if (fullText.includes('Recruiting')) {
      status = 'Recruiting';
    }

    // Phase
    const phaseMatch = fullText.match(/Phase\s*\n\s*(Phase\s*[1-4](?:\/[1-4])?|Early Phase 1|Phase Not Applicable|Not Applicable)/i) ||
                       fullText.match(/Phases\s*\n\s*([^\n]+)/i) ||
                       fullText.match(/(Phase\s*[1-4](?:\/[1-4])?|Early Phase 1)/i);
    const phase = phaseMatch ? phaseMatch[1].trim() : 'N/A';

    // Interventions from #study-overview
    const overview = document.querySelector('#study-overview')?.innerText || '';
    const intrMatch = overview.match(/Intervention\/Treatment\s*\n([\s\S]*?)(?:\n\n|\n[A-Z][a-zA-Z\s\/]+:|\nOther Study ID|\nStudy Start|$)/i);
    const intervention = intrMatch ? intrMatch[1].trim().replace(/\n+/g, '; ') : 'Intervention details in record';

    // Locations from #contacts-and-locations
    const locSection = document.querySelector('#contacts-and-locations')?.innerText || '';
    // Look for locations text
    const usLocMatch = locSection.match(/United States([\s\S]*?)(?:Click to view interactive map|Participation Criteria|Collaborators and Investigators|$)/i);
    let locations = '';
    if (usLocMatch) {
      const lines = usLocMatch[1].split('\n').map(s => s.trim()).filter(s => s.length > 0 && !s.includes('Recruiting') && !s.includes('Contact :') && !s.includes('Locations') && !s.includes('Principal Investigator') && !s.includes('Sub-Investigator') && !s.includes('Phone Number') && !s.includes('Email:'));
      locations = lines.slice(0, 10).join('; ');
    } else {
      locations = 'United States locations listed on record';
    }

    return { title, status, phase, intervention, locations, url: window.location.href.split('?')[0] };
  });

  allTrials.push({
    tabId,
    nct,
    ...extracted
  });
}

await write("tmp://trials_data.json", JSON.stringify(allTrials, null, 2));
console.log(`Saved ${allTrials.length} trials so far.`);

