const trials = JSON.parse((await read("tmp://trials_data.json")).text);

for (const t of trials) {
  const fullLocs = await browserjs(t.tabId, () => {
    const locSection = document.querySelector('#contacts-and-locations');
    if (!locSection) return [];

    // Find all location entries: on clinicaltrials.gov, each location facility is often inside a div or list item
    // Let's get the text of all elements with facility names, cities, states
    const lines = locSection.innerText.split('\n').map(l => l.trim()).filter(Boolean);
    const usIdx = lines.findIndex(l => l === 'United States');
    if (usIdx === -1) return lines.slice(0, 15);

    // Slice from 'United States'
    const usLines = lines.slice(usIdx);
    // Find locations
    const facilityList = [];
    for (let i = 0; i < usLines.length; i++) {
      const line = usLines[i];
      if (line.includes('Locations') || line === 'United States' || line.includes('Click to view') || line.includes('Participation Criteria')) continue;
      if (line.includes(', United States')) {
        // e.g., "Baltimore, Maryland, United States, 21224"
        const cityState = line.split(', United States')[0];
        // The next lines might be status, facility name, contact
        let facility = '';
        for (let j = i + 1; j < Math.min(i + 5, usLines.length); j++) {
          const nextL = usLines[j];
          if (nextL.includes(', United States') || nextL.includes('Locations') || nextL.includes('Click to view')) break;
          if (nextL !== 'Recruiting' && nextL !== 'Active, not recruiting' && !nextL.startsWith('Contact :') && !nextL.startsWith('Study Coordinator') && !nextL.match(/^\d{3}-\d{3}/) && !nextL.includes('@') && !nextL.startsWith('Site ')) {
            facility = nextL;
            break;
          }
        }
        facilityList.push(facility ? `${facility} (${cityState})` : cityState);
      }
    }
    return facilityList;
  });

  if (fullLocs && fullLocs.length > 0) {
    t.locationsList = fullLocs;
    t.locationsFormatted = fullLocs.slice(0, 5).join('; ') + (fullLocs.length > 5 ? ` (and ${fullLocs.length - 5} more U.S. sites)` : '');
  } else {
    t.locationsFormatted = t.locations;
  }
}

await write("tmp://trials_data.json", JSON.stringify(trials, null, 2));

trials.forEach((t, i) => {
  console.log(`${i+1}. [${t.nct}] ${t.title}`);
  console.log(`   Phase: ${t.phase} | Status: ${t.status}`);
  console.log(`   Intervention: ${t.intervention}`);
  console.log(`   Locations: ${t.locationsFormatted}`);
});

