let allMatched = true;
for (const [idx, t] of trials.entries()) {
  const matchTab = tabsContext.pages.find(p => p.tabId === t.tabId);
  if (!matchTab) {
    console.error(`Trial ${idx + 1} (${t.nct}) tab ${t.tabId} NOT found in open tabs!`);
    allMatched = false;
  } else {
    console.log(`Trial ${idx + 1} [Tab ${t.tabId}]: ${t.nct} -> ${matchTab.url} (Title: ${matchTab.title})`);
  }
}

console.log("All trials matched open tabs:", allMatched);

// Check CryptPad tab
const cryptpadTab = tabsContext.pages.find(p => p.tabId === 787784156);
console.log("CryptPad tab:", cryptpadTab);

if (allMatched && cryptpadTab) {
  await edit({
    path: todoPath,
    edits: [{
